(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-955":{scenario:{company:"Tam Giang Aqua JSC",supervisor:{name:"Lâm Hoàng Phúc",role:{vi:"Giám đốc kỹ thuật trại nuôi",en:"Farm Technical Director"}},ref_code:"AO-A3-1104",title:{vi:"Đọc đúng nước ao. Chọn đúng hóa chất. Tính đúng liều.",en:"Read the water. Pick the right agent. Dose it right."},brief:{vi:"Bạn xử lý phiếu điều chỉnh môi trường AO-A3-1104 cho ao tôm thẻ chân trắng A3 (ngày nuôi 52). Ao rộng 2500 m2, mực nước đo thực tế 1.2 m (thiết kế 1.5 m). Độ kiềm đo được 100 mg/L CaCO3, mục tiêu 140 mg/L; pH dao động 7.9-8.4, TAN 2.1 mg/L. Dùng terminal đọc dữ liệu, sửa hóa chất tăng kiềm và khối lượng cần dùng (kg), rồi lập báo cáo có căn cứ.",en:"You are handling water-quality adjustment sheet AO-A3-1104 for whiteleg shrimp pond A3 (day 52). The pond is 2500 m2 with a measured water depth of 1.2 m (design 1.5 m). Alkalinity is 100 mg/L as CaCO3 against a target of 140 mg/L; pH swings 7.9-8.4 and TAN is 2.1 mg/L. Use the terminal to read the data, correct the alkalinity agent and the required amount (kg), then write an evidence-based report."},reference_title:{vi:"Nhật ký chất lượng nước & bảng liều hóa chất đã duyệt · AO-A3",en:"Approved water-quality log & dosing table · AO-A3"},fields:[{id:"ALK_AGENT",label:{vi:"Hóa chất tăng độ kiềm",en:"Alkalinity agent"},initial:"CaO",expected:"NaHCO3",choices:["CaO","NaHCO3","CaCO3"],reference:"Bảng lựa chọn hóa chất theo pH",hint:{vi:"pH và TAN cao thì phải tăng kiềm mà không đẩy pH: vôi nung làm tăng NH3 độc, CaCO3 tan kém khi pH trên 8.",en:"With high pH and TAN, raise alkalinity without pushing pH: quicklime increases toxic NH3 and CaCO3 dissolves poorly above pH 8."}},{id:"NAHCO3_KG",label:{vi:"Khối lượng hóa chất cần dùng (kg)",en:"Required amount (kg)"},initial:"252",expected:"201.6",reference:"Phiếu đo mực nước & độ kiềm",ref_value:{vi:"Diện tích 2500 m2; mực nước đo 1.2 m; kiềm 100 mg/L, mục tiêu 140 mg/L",en:"Area 2500 m2; measured depth 1.2 m; alkalinity 100 mg/L, target 140 mg/L"},hint:{vi:"Thể tích ao tính theo mực nước đo thực tế, không theo độ sâu thiết kế.",en:"Pond volume uses the measured water level, not the design depth."}}],sop32:{vi:"Khối lượng NaHCO3 (kg) = mức tăng kiềm (mg/L) x thể tích nước thực tế (m3) x 1.68 / 1000; thể tích = diện tích x mực nước đo.",en:"NaHCO3 (kg) = alkalinity increase (mg/L) x actual water volume (m3) x 1.68 / 1000; volume = area x measured depth."},context:{label:"AQUA-SCADA / AO-A3",metrics:[{label:{vi:"Diện tích ao",en:"Pond area"},value:"2500 m2"},{label:{vi:"Mực nước đo",en:"Measured depth"},value:"1.2 m"},{label:{vi:"Độ kiềm đo / mục tiêu",en:"Alkalinity now / target"},value:"100 / 140 mg/L"}]},crisis:{vi:"Quản lý trại nhắn: “Ao A5 bên cạnh nghi bị hoại tử gan tụy cấp, đêm nay xả hết nước ra kênh chung cho nhanh, đừng báo thú y kẻo cả vùng bị khoanh dịch.”",en:"The farm manager messages you: “Pond A5 next door looks like acute hepatopancreatic necrosis, drain it all into the shared canal tonight and don't tell the vets or the whole area will be quarantined.”"},options:{safe:{vi:"Không xả nước ao bệnh ra kênh; cách ly ao A5, xử lý nước trong ao theo quy trình diệt khuẩn đã duyệt, báo giám đốc kỹ thuật và cơ quan thú y địa phương, lấy mẫu xét nghiệm xác định bệnh.",en:"Do not drain the sick pond into the canal; isolate pond A5, disinfect the water in place per the approved procedure, inform the technical director and local veterinary authority and send samples for diagnosis."},shortcut:{vi:"Xả nước ao A5 ra kênh trong đêm và không báo cáo để tránh bị khoanh vùng dịch.",en:"Drain pond A5 into the canal overnight and report nothing to avoid quarantine."},wait:{vi:"Không can thiệp ao A5, chờ quản lý trại tự quyết định.",en:"Leave pond A5 alone and let the farm manager decide."}},questions:{vi:["Vì sao chọn NaHCO3 và cần 201.6 kg cho ao A3? Số liệu nào trong terminal chứng minh?","Bạn xử lý yêu cầu xả nước ao nghi nhiễm bệnh ra kênh chung thế nào để đúng quy định và bảo vệ cả vùng nuôi?"],en:["Why did you choose NaHCO3 and why does pond A3 need 201.6 kg? Which terminal data proves it?","How do you handle the request to drain a suspected diseased pond into the shared canal lawfully while protecting the whole farming area?"]},hints:{vi:["Chạy cat water.log và cat dosing.txt, so pH, TAN với điều kiện dùng từng hóa chất.","Lấy thể tích từ mực nước trong cat level.log rồi áp dụng công thức SOP mục 3.2.","Đọc lại SOP mục 4.2: nước ao nghi nhiễm bệnh phải được xử lý trước khi thải và phải báo cơ quan thú y."],en:["Run cat water.log and cat dosing.txt and compare pH and TAN with each agent's conditions.","Take the volume from the level in cat level.log and apply the SOP 3.2 formula.","Re-read SOP 4.2: water from a suspected diseased pond must be treated before discharge and reported to the vets."]},terminal:{system:"aqua-scada",settable:["ALK_AGENT","NAHCO3_KG"],commands:[{cmd:"status",out:{vi:"Ao A3 · tôm thẻ ngày 52 · mật độ 120 con/m2 · 6 máy quạt nước đang chạy · cảnh báo: độ kiềm thấp",en:"Pond A3 · whiteleg shrimp day 52 · 120 shrimp/m2 · 6 paddlewheels running · alert: low alkalinity"}},{cmd:"cat water.log",out:{vi:"06:00 pH 7.9, DO 4.3 mg/L · 14:00 pH 8.4 · kiềm 100 mg/L CaCO3 · TAN 2.1 mg/L · nhiệt độ 30°C",en:"06:00 pH 7.9, DO 4.3 mg/L · 14:00 pH 8.4 · alkalinity 100 mg/L CaCO3 · TAN 2.1 mg/L · 30°C"}},{cmd:"cat level.log",out:{vi:"Cảm biến mực nước A3: 1.20 m (thiết kế 1.50 m) · hao hụt do bốc hơi, chưa cấp bù",en:"Pond A3 level sensor: 1.20 m (design 1.50 m) · evaporation loss, not yet topped up"}},{cmd:"cat dosing.txt",out:{vi:"NaHCO3: 1.68 kg/1000 m3 cho mỗi 1 mg/L kiềm · CaO: tăng pH nhanh, không dùng khi TAN cao · CaCO3: tan kém khi pH trên 8",en:"NaHCO3: 1.68 kg per 1000 m3 per 1 mg/L alkalinity · CaO: raises pH fast, not with high TAN · CaCO3: dissolves poorly above pH 8"}},{cmd:"cat target.txt",out:{vi:"Mục tiêu tuần: kiềm 140 mg/L CaCO3 · pH dao động ngày không quá 0.5 · DO sáng sớm ≥ 4 mg/L",en:"Weekly targets: alkalinity 140 mg/L CaCO3 · daily pH swing no more than 0.5 · dawn DO ≥ 4 mg/L"}}]}},learning:{summary:{vi:"Kỹ sư nuôi trồng thủy sản thiết kế, vận hành và tối ưu hệ thống nuôi tôm, cá: chuẩn bị ao, quản lý chất lượng nước, thức ăn, sức khỏe vật nuôi, an toàn sinh học và xử lý nước thải. Nghề quyết định tỷ lệ sống, hệ số chuyển đổi thức ăn và giá thành mỗi kg sản phẩm; đòi hỏi hiểu hóa học nước, sinh học vật nuôi, vận hành thiết bị và tuân thủ quy định thú y, môi trường.",en:"An aquaculture engineer designs, operates and optimises shrimp and fish farming systems: pond preparation, water quality, feed, animal health, biosecurity and effluent treatment. The role drives survival rate, feed conversion and cost per kilogram; it requires water chemistry, animal biology, equipment operation and compliance with veterinary and environmental rules."},responsibilities:{vi:["Lập kế hoạch vụ nuôi: chuẩn bị ao, chọn giống sạch bệnh, mật độ thả và lịch cho ăn.","Đo và điều chỉnh chất lượng nước: DO, pH, độ kiềm, TAN, nitrit, độ mặn.","Quản lý thức ăn, theo dõi tăng trưởng, hệ số chuyển đổi thức ăn (FCR) và tỷ lệ sống.","Vận hành hệ thống quạt nước, lọc, ao lắng và xử lý nước thải.","Giám sát sức khỏe, an toàn sinh học và phối hợp với thú y khi có dấu hiệu dịch bệnh."],en:["Plan the crop: pond preparation, disease-free seed, stocking density and feeding schedule.","Measure and adjust water quality: DO, pH, alkalinity, TAN, nitrite and salinity.","Manage feed and track growth, feed conversion ratio (FCR) and survival.","Run aerators, filters, settling ponds and effluent treatment.","Monitor health and biosecurity and work with the vets at the first sign of disease."]},competencies:[{name:{vi:"Hóa học & sinh học nước",en:"Water chemistry & biology"},desc:{vi:"Hiểu quan hệ pH, độ kiềm, CO2, tảo, amoniac và oxy hòa tan trong ao.",en:"Understand how pH, alkalinity, CO2, algae, ammonia and dissolved oxygen interact."}},{name:{vi:"Quản lý thức ăn & tăng trưởng",en:"Feed & growth management"},desc:{vi:"Điều chỉnh lượng ăn theo nhá, sức khỏe và thời tiết để tối ưu FCR.",en:"Adjust feeding by tray checks, health and weather to optimise FCR."}},{name:{vi:"Vận hành hệ thống nuôi",en:"System operation"},desc:{vi:"Vận hành, bảo trì quạt nước, máy thổi khí, cảm biến và hệ thống xử lý nước.",en:"Operate and maintain paddlewheels, blowers, sensors and water treatment."}},{name:{vi:"An toàn sinh học thủy sản",en:"Aquatic biosecurity"},desc:{vi:"Ngăn mầm bệnh xâm nhập qua giống, nước, dụng cụ và xử lý ao bệnh đúng quy trình.",en:"Keep pathogens out via seed, water and tools and handle diseased ponds correctly."}},{name:{vi:"Ra quyết định dựa trên dữ liệu",en:"Data-driven decisions"},desc:{vi:"Dùng số đo thực tế để tính liều hóa chất, lượng ăn và thời điểm thu hoạch.",en:"Use real measurements to set chemical doses, feed rates and harvest timing."}}],knowledge:{vi:["Luật Thủy sản số 18/2017/QH14 và các quy định về điều kiện cơ sở nuôi trồng thủy sản.","Luật Thú y số 79/2015/QH13 về phòng, chống dịch bệnh động vật thủy sản.","Cân bằng CO2, pH, độ kiềm và tỷ lệ amoniac tự do (NH3) tăng theo pH, nhiệt độ.","VietGAP trong nuôi trồng thủy sản và các tiêu chuẩn nuôi có trách nhiệm.","Các bệnh chính trên tôm: hoại tử gan tụy cấp (AHPND), đốm trắng (WSSV), vi bào tử trùng (EHP)."],en:["Fisheries Law No. 18/2017/QH14 and rules on aquaculture facility conditions.","Veterinary Law No. 79/2015/QH13 on aquatic animal disease prevention and control.","The CO2, pH and alkalinity balance and how free ammonia (NH3) rises with pH and temperature.","VietGAP for aquaculture and responsible farming standards.","Major shrimp diseases: acute hepatopancreatic necrosis (AHPND), white spot (WSSV) and EHP."]},tools:["Máy đo DO, pH cầm tay","Bộ test kiềm, TAN, nitrit","Cảm biến chất lượng nước trực tuyến","Máy quạt nước & máy thổi khí","Phần mềm quản lý vụ nuôi"],kpis:{vi:["Tỷ lệ sống đến khi thu hoạch.","Hệ số chuyển đổi thức ăn (FCR) so với mục tiêu.","Giá thành sản xuất trên mỗi kg tôm.","Số ngày chỉ tiêu nước nằm ngoài ngưỡng an toàn."],en:["Survival rate at harvest.","Feed conversion ratio (FCR) versus target.","Production cost per kilogram of shrimp.","Days with water parameters outside safe limits."]},day:[{time:"05:30",vi:"Đo DO, pH sáng sớm và kiểm tra hoạt động của quạt nước.",en:"Measure dawn DO and pH and check the paddlewheels."},{time:"07:00",vi:"Cho ăn cữ sáng, kiểm tra nhá để điều chỉnh lượng thức ăn.",en:"Give the morning feed and check trays to adjust the ration."},{time:"10:00",vi:"Đo độ kiềm, TAN, nitrit và quyết định bổ sung hóa chất.",en:"Test alkalinity, TAN and nitrite and decide on chemical additions."},{time:"14:00",vi:"Đo pH buổi chiều, chài mẫu kiểm tra tăng trưởng và sức khỏe tôm.",en:"Measure afternoon pH and cast-net samples to check growth and health."},{time:"17:00",vi:"Cập nhật nhật ký ao và lập kế hoạch cho ngày hôm sau.",en:"Update the pond log and plan the next day."}],mistakes:{vi:["Tính liều hóa chất theo độ sâu thiết kế thay vì mực nước thực tế.","Dùng vôi nung khi pH và TAN cao, làm tăng amoniac tự do gây độc cho tôm.","Xả nước ao bệnh chưa xử lý ra kênh chung, làm lây dịch cho cả vùng."],en:["Dosing chemicals by design depth instead of the actual water level.","Using quicklime with high pH and TAN, raising toxic free ammonia.","Draining untreated water from a diseased pond into the shared canal and spreading disease."]},career:[{vi:"Kỹ thuật viên ao nuôi",en:"Pond technician"},{vi:"Kỹ sư nuôi trồng thủy sản",en:"Aquaculture engineer"},{vi:"Trưởng trại nuôi",en:"Farm manager"},{vi:"Giám đốc kỹ thuật vùng nuôi",en:"Regional aquaculture technical director"}],glossary:[{term:"FCR",vi:"Hệ số chuyển đổi thức ăn: số kg thức ăn cần để tạo 1 kg tăng trọng.",en:"Feed conversion ratio: kilograms of feed per kilogram of weight gain."},{term:"TAN",vi:"Tổng amoni (NH3 + NH4+) trong nước; phần NH3 tự do là dạng độc với tôm cá.",en:"Total ammonia nitrogen (NH3 + NH4+); the free NH3 fraction is toxic to shrimp and fish."},{term:"Alkalinity",vi:"Độ kiềm: khả năng đệm pH của nước, tính bằng mg/L CaCO3.",en:"The water's pH buffering capacity, expressed as mg/L CaCO3."},{term:"DO",vi:"Oxy hòa tan trong nước, thường thấp nhất vào sáng sớm.",en:"Dissolved oxygen in water, usually lowest at dawn."},{term:"Biosecurity",vi:"An toàn sinh học: biện pháp ngăn mầm bệnh xâm nhập và lây lan giữa các ao, các trại.",en:"Measures preventing pathogens from entering and spreading between ponds and farms."}],quiz:[{q:{vi:"Khi pH tăng, tỷ lệ amoniac tự do (NH3) trong tổng amoni thay đổi thế nào?",en:"As pH rises, how does the share of free ammonia (NH3) in total ammonia change?"},options:{vi:["Giảm","Không đổi","Tăng","Bằng không"],en:["Decreases","Stays the same","Increases","Drops to zero"]},answer:2,explain:{vi:"pH càng cao, cân bằng càng chuyển về NH3 tự do, dạng độc với tôm cá.",en:"The higher the pH, the more the balance shifts to free NH3, the toxic form."}},{q:{vi:"Ao 4000 m2, mực nước 1 m, cần tăng kiềm 20 mg/L; hệ số 1.68 kg NaHCO3/1000 m3 cho mỗi 1 mg/L. Cần bao nhiêu kg?",en:"A 4000 m2 pond at 1 m depth needs 20 mg/L more alkalinity; factor 1.68 kg NaHCO3 per 1000 m3 per 1 mg/L. How many kg?"},options:{vi:["134.4 kg","168 kg","80 kg","33.6 kg"],en:["134.4 kg","168 kg","80 kg","33.6 kg"]},answer:0,explain:{vi:"Khối lượng = 20 x 4000 x 1.68 / 1000 = 134.4 kg.",en:"Amount = 20 x 4000 x 1.68 / 1000 = 134.4 kg."}},{q:{vi:"Ao nghi nhiễm bệnh, quản lý muốn xả nước ra kênh chung ngay. Bạn làm gì?",en:"A pond is suspected of disease and the manager wants to drain it into the canal now. What do you do?"},options:{vi:["Xả vào ban đêm","Pha loãng rồi xả","Bơm sang ao khác","Cách ly, xử lý nước trong ao và báo cơ quan thú y"],en:["Drain it at night","Dilute and drain","Pump it into another pond","Isolate, treat the water in place and notify the vets"]},answer:3,explain:{vi:"Xả nước ao bệnh chưa xử lý làm lây lan dịch cho cả vùng và vi phạm quy định thú y, môi trường.",en:"Draining untreated diseased water spreads infection across the area and breaks veterinary and environmental rules."}},{q:{vi:"FCR bằng 1.3 nghĩa là gì?",en:"What does an FCR of 1.3 mean?"},options:{vi:["1.3 tấn tôm mỗi ha","Cần 1.3 kg thức ăn để tạo 1 kg tôm tăng trọng","Tỷ lệ sống 130%","Cho ăn 1.3 lần mỗi ngày"],en:["1.3 tonnes of shrimp per ha","1.3 kg of feed produces 1 kg of shrimp gain","130% survival","1.3 feedings per day"]},answer:1,explain:{vi:"FCR là tỷ lệ giữa lượng thức ăn tiêu thụ và khối lượng tăng trọng; càng thấp càng hiệu quả.",en:"FCR is feed consumed divided by weight gained; lower is more efficient."}}],tools_en:["Handheld DO and pH meter","Alkalinity, TAN and nitrite test kits","Online water quality sensors","Paddlewheel aerators & air blowers","Grow-out cycle management software"]}}})})(window.KKR);
